require_once __DIR__.'/includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$pass=$_POST['senha']??'';if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Informe nome, e-mail válido e senha com pelo menos 8 caracteres.';else{try{$s=db()->prepare("INSERT INTO usuarios (nome,email,senha,perfil) VALUES (?,?,?,'cliente')");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);header('Location: login.php?cadastro=ok');exit;}catch(PDOException $e){$error=$e->getCode()==='23000'?'Este e-mail já está cadastrado.':'Não foi possível criar a conta.';}}}
$pageTitle='Cadastro';require __DIR__.'/includes/header.php';?>
<div class="auth-card card mx-auto"><div class="card-body p-4"><h1 class="h3">Criar conta</h1><?php if(!empty($error)): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><label class="form-label">Nome</label><input class="form-control mb-3" name="nome" required minlength="2"><label class="form-label">E-mail</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Senha (mínimo 8 caracteres)</label><input class="form-control mb-3" type="password" name="senha" minlength="8" required><button class="btn btn-dark w-100">Cadastrar</button></form></div></div>
